"use client";

import { describeWeakPassword } from "@exwave-nexus/auth/messages";
import {
  useEmailLink,
  useExwave,
  usePasswordCheck,
  usePasswordReset,
} from "@exwave-nexus/auth-react";
import { type ComponentProps, type FormEvent, useId, useState } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import { PasswordRules } from "@/components/exwave/password-rules";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

/** The page password reset emails link to: choose a new password, then sign in. */
export function ResetPasswordForm({
  className,
  ...props
}: ComponentProps<"div">) {
  const id = useId();
  const { navigate, paths, messages } = useExwave();
  const link = useEmailLink();
  const { confirm, policy } = usePasswordReset();
  const [password, setPassword] = useState("");
  const [tried, setTried] = useState(false);
  const check = usePasswordCheck(password, policy);
  const error =
    tried && !check.valid
      ? describeWeakPassword(check.failed, { policy, messages })
      : confirm.message;

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTried(true);
    if (link.status !== "reset" || !check.valid) return;
    const session = await confirm.run(
      { userId: link.userId, code: link.code },
      password,
    );
    if (session) navigate(paths.afterSignIn, { replace: true });
  }

  if (link.status === "loading") return null;

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Choose a new password</CardTitle>
          <CardDescription>
            {link.status === "reset" ? (
              "You'll be signed in once it's saved."
            ) : (
              <>
                Open this page from the link in your password reset email.{" "}
                <AuthLink
                  href={paths.forgotPassword}
                  className="underline underline-offset-4"
                >
                  Send a new link
                </AuthLink>
              </>
            )}
          </CardDescription>
        </CardHeader>
        {link.status === "reset" && (
          <CardContent>
            <form onSubmit={onSubmit} aria-busy={confirm.pending}>
              <div className="flex flex-col gap-6">
                <div className="grid gap-2">
                  <Label htmlFor={`${id}-password`}>New password</Label>
                  <Input
                    id={`${id}-password`}
                    type="password"
                    autoComplete="new-password"
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                    aria-invalid={error ? true : undefined}
                    aria-describedby={`${id}-rules`}
                    required
                  />
                  <PasswordRules id={`${id}-rules`} check={check} />
                </div>
                {error && (
                  <p role="alert" className="text-sm text-destructive">
                    {error}
                  </p>
                )}
                <Button
                  type="submit"
                  className="w-full"
                  disabled={confirm.pending}
                >
                  {confirm.pending ? "Saving…" : "Save and sign in"}
                </Button>
              </div>
            </form>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

"use client";

import { useExwave } from "@exwave-nexus/auth-react";
import type { ComponentProps, MouseEvent } from "react";

/** A link between auth pages that moves the way your app does (the provider's `navigate`). */
export function AuthLink({
  href,
  onClick,
  ...props
}: ComponentProps<"a"> & { href: string }) {
  const { navigate } = useExwave();
  const follow = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      props.target
    )
      return;
    event.preventDefault();
    navigate(href);
  };
  return <a href={href} onClick={follow} {...props} />;
}

/** `?redirect=/path` from the address bar when it stays on this site, else `fallback`. */
export function redirectTarget(fallback: string): string {
  if (typeof location === "undefined") return fallback;
  const to = new URLSearchParams(location.search).get("redirect");
  return to?.startsWith("/") && !to.startsWith("//") && !to.startsWith("/\\")
    ? to
    : fallback;
}

"use client";

import type { PasswordCheck } from "@exwave-nexus/auth-react";
import { Check, Circle } from "lucide-react";
import { cn } from "@/lib/utils";

/** The platform's password rules, ticked off as the password is typed. */
export function PasswordRules({
  check,
  id,
  className,
}: {
  check: PasswordCheck;
  id?: string;
  className?: string;
}) {
  if (check.rules.length === 0) return null;
  return (
    <ul id={id} className={cn("grid gap-1 text-sm", className)}>
      {check.rules.map(({ rule, ok, label }) => (
        <li
          key={rule}
          className={cn(
            "flex items-center gap-2",
            ok ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {ok ? (
            <Check className="size-3.5" aria-hidden="true" />
          ) : (
            <Circle className="size-3.5" aria-hidden="true" />
          )}
          <span>
            {label}
            <span className="sr-only">{ok ? " (done)" : " (needed)"}</span>
          </span>
        </li>
      ))}
    </ul>
  );
}
